1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUM_BY_ITEM_TYPE = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	  rune: 25,
9	  moonstone: 25,
10	} as const satisfies Record<string, number>;
11	
12	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
13	
14	const INSURANCE_VALUE_BY_ITEM_TYPE = {
15	  sword: 1000,
16	  amulet: 600,
17	  staff: 800,
18	  potion: 400,
19	  rune: 250,
20	  moonstone: 250,
21	} as const satisfies Record<InsurableItemType, number>;
22	
23	const DEDUCTIBLE_PER_DAMAGE = 100;
24	
25	// Distinct from HIGH_ENCHANTMENT_THRESHOLD: that one raises the premium at
26	// level 5, this one halves the reimbursement at level 8.
27	const REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
28	
29	const REIMBURSEMENT_ENCHANTMENT_RATE = 0.5;
30	
31	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
32	
33	const BLOCK_SIZE = 3;
34	
35	const BLOCK_BASE_PREMIUM = 60;
36	
37	const CURSE_SURCHARGE_RATE = 0.5;
38	
39	const HIGH_ENCHANTMENT_THRESHOLD = 5;
40	
41	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
42	
43	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
44	
45	const LOYALTY_YEARS_THRESHOLD = 2;
46	
47	const LOYALTY_DISCOUNT_RATE = 0.2;
48	
49	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
50	
51	export type QuoteResult = { premium: number };
52	
53	export type ClaimResult = { payout: number; remainingCap: number };
54	
55	export type ScenarioResult = QuoteResult | ClaimResult;
56	
57	export type ScenarioOutcome = { results: ScenarioResult[] };
58	
59	type Item = {
60	  type: InsurableItemType;
61	  cursed?: boolean;
62	  enchantment?: number;
63	};
64	
65	type Customer = { yearsWithMHPCO: number };
66	
67	type QuoteStep = { op: "quote"; items: Item[] };
68	
69	type Damage = { itemType: string; amount: number };
70	
71	type ClaimStep = {
72	  op: "claim";
73	  policy: number;
74	  incident: { cause: string; damages: Damage[] };
75	};
76	
77	type Step = QuoteStep | ClaimStep;
78	
79	type Scenario = { customer: Customer; steps: Step[] };
80	
81	// Amounts are rounded in the MHPCO's favour: premiums (charged to the
82	// customer) round up.
83	const roundPremiumInMHPCOsFavour = (amount: number): number =>
84	  Math.ceil(amount);
85	
86	const countByItemType = (items: Item[]): Map<InsurableItemType, number> => {
87	  const counts = new Map<InsurableItemType, number>();
88	
89	  for (const item of items) {
90	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
91	  }
92	
93	  return counts;
94	};
95	
96	// Exactly 3 alike components form a building block at a special base premium.
97	const basePremiumForAlikeItems = (
98	  type: InsurableItemType,
99	  count: number,
100	): number =>
101	  count === BLOCK_SIZE
102	    ? BLOCK_BASE_PREMIUM
103	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
104	
105	const basePremiumOf = (items: Item[]): number =>
106	  [...countByItemType(items)]
107	    .map(([type, count]) => basePremiumForAlikeItems(type, count))
108	    .reduce((total, premium) => total + premium, 0);
109	
110	const ownBasePremiumOf = (item: Item): number =>
111	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
112	
113	// Item-specific modifiers apply to the affected item's own base premium,
114	// not to the policy total.
115	type ItemModifier = { appliesTo: (item: Item) => boolean; rate: number };
116	
117	const CURSE_MODIFIER: ItemModifier = {
118	  appliesTo: (item) => item.cursed === true,
119	  rate: CURSE_SURCHARGE_RATE,
120	};
121	
122	const HIGH_ENCHANTMENT_MODIFIER: ItemModifier = {
123	  appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
124	  rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
125	};
126	
127	const ITEM_MODIFIERS: ItemModifier[] = [
128	  CURSE_MODIFIER,
129	  HIGH_ENCHANTMENT_MODIFIER,
130	];
131	
132	const itemSurchargeOf = (items: Item[], modifier: ItemModifier): number =>
133	  items
134	    .filter(modifier.appliesTo)
135	    .reduce((total, item) => total + ownBasePremiumOf(item) * modifier.rate, 0);
136	
137	// Item modifiers accumulate: an item matching several of them pays each
138	// surcharge on its own base premium.
139	const itemSurchargesOf = (items: Item[]): number =>
140	  ITEM_MODIFIERS.reduce(
141	    (total, modifier) => total + itemSurchargeOf(items, modifier),
142	    0,
143	  );
144	
145	// Policy-wide modifiers are computed from the policy base premium, so the
146	// first insurance surcharge is 10 % of the base — not of base plus curse.
147	// A modifier's rate is signed: surcharges are positive, discounts negative.
148	type PolicyContext = { customer: Customer; precedingQuotes: number };
149	
150	type PolicyModifier = {
151	  appliesTo: (context: PolicyContext) => boolean;
152	  rate: number;
153	};
154	
155	const FIRST_INSURANCE_MODIFIER: PolicyModifier = {
156	  appliesTo: () => true,
157	  rate: FIRST_INSURANCE_SURCHARGE_RATE,
158	};
159	
160	const LOYALTY_MODIFIER: PolicyModifier = {
161	  appliesTo: ({ customer }) =>
162	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
163	  rate: -LOYALTY_DISCOUNT_RATE,
164	};
165	
166	// Each item in a quote counts as a first insurance regardless of customer
167	// history, so this discount stacks with the first insurance surcharge.
168	const FOLLOW_UP_CONTRACT_MODIFIER: PolicyModifier = {
169	  appliesTo: ({ precedingQuotes }) => precedingQuotes >= 1,
170	  rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
171	};
172	
173	const POLICY_MODIFIERS: PolicyModifier[] = [
174	  FIRST_INSURANCE_MODIFIER,
175	  LOYALTY_MODIFIER,
176	  FOLLOW_UP_CONTRACT_MODIFIER,
177	];
178	
179	// Policy modifiers accumulate: each applicable one is computed on the same
180	// policy base premium, never compounded on top of another.
181	const policyAdjustmentOf = (
182	  basePremium: number,
183	  context: PolicyContext,
184	): number =>
185	  POLICY_MODIFIERS.filter((modifier) => modifier.appliesTo(context)).reduce(
186	    (total, modifier) => total + basePremium * modifier.rate,
187	    0,
188	  );
189	
190	const quotePremium = (items: Item[], context: PolicyContext): number => {
191	  const basePremium = basePremiumOf(items);
192	
193	  return roundPremiumInMHPCOsFavour(
194	    basePremium +
195	      itemSurchargesOf(items) +
196	      policyAdjustmentOf(basePremium, context) +
197	      PROCESSING_FEE,
198	  );
199	};
200	
201	const insuranceSumOf = (items: Item[]): number =>
202	  items.reduce(
203	    (total, item) => total + INSURANCE_VALUE_BY_ITEM_TYPE[item.type],
204	    0,
205	  );
206	
207	// A reimbursement clause reduces the damage amount to a fraction of itself,
208	// keyed on the insured item's attributes — which the damage entry does not
209	// carry, it names only the item type. Same {appliesTo, rate} shape as
210	// ItemModifier, but the rate is a share of the damage rather than a surcharge
211	// on a base premium. Only one clause exists so far, so the selection below is
212	// a plain conditional; a second clause will need a rule for which one wins.
213	type ReimbursementClause = { appliesTo: (item: Item) => boolean; rate: number };
214	
215	const HIGH_ENCHANTMENT_CLAUSE: ReimbursementClause = {
216	  appliesTo: (item) =>
217	    (item.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_THRESHOLD,
218	  rate: REIMBURSEMENT_ENCHANTMENT_RATE,
219	};
220	
221	const FULL_REIMBURSEMENT_RATE = 1;
222	
223	const reimbursementRateFor = (insuredItem: Item): number =>
224	  HIGH_ENCHANTMENT_CLAUSE.appliesTo(insuredItem)
225	    ? HIGH_ENCHANTMENT_CLAUSE.rate
226	    : FULL_REIMBURSEMENT_RATE;
227	
228	const reimbursementFor = (damageAmount: number, insuredItem: Item): number =>
229	  damageAmount * reimbursementRateFor(insuredItem);
230	
231	// Each damage entry is a distinct damaged item, so it claims one insured item
232	// of that type and no other entry may claim the same one.
233	const claimInsuredItem = (
234	  damage: Damage,
235	  unclaimedItems: Item[],
236	): { insuredItem: Item; remainingItems: Item[] } => {
237	  const index = unclaimedItems.findIndex(
238	    (item) => item.type === damage.itemType,
239	  );
240	
241	  if (index === -1) {
242	    throw new Error(
243	      `the policy does not cover a damaged ${damage.itemType}`,
244	    );
245	  }
246	
247	  return {
248	    insuredItem: unclaimedItems[index],
249	    remainingItems: unclaimedItems.filter((_, at) => at !== index),
250	  };
251	};
252	
253	// Rejecting a damage entry is kept apart from pricing it, so payoutForDamage
254	// below is purely a calculation and its name stays true. Zero is a valid
255	// amount: the spec rejects only negative ones.
256	//
257	// Both throw sites here (this one and claimInsuredItem) raise a plain Error,
258	// as will the pending unknown-item-type-in-a-quote case. A named error type
259	// was reconsidered at this second throw site and again deferred: the reason is
260	// no longer "only one implementor" but that no consumer discriminates between
261	// them — every test asserts a bare .toThrow(), and all three cases mean the
262	// same thing, "the submitted scenario is invalid". The CLI is the first real
263	// consumer; introduce a type when a CLI test demands different handling per
264	// cause, not merely a non-zero exit.
265	// The MHPCO insures only the item types on its price list.
266	const rejectUninsurableItem = (item: Item): void => {
267	  if (!(item.type in BASE_PREMIUM_BY_ITEM_TYPE)) {
268	    throw new Error(`the MHPCO does not insure a ${item.type}`);
269	  }
270	};
271	
272	const rejectInvalidDamage = (damage: Damage): void => {
273	  if (damage.amount < 0) {
274	    throw new Error(
275	      `the damage to the ${damage.itemType} is a negative amount`,
276	    );
277	  }
278	};
279	
280	// A deductible applies per damage event, i.e. once per damaged item.
281	const payoutForDamage = (damage: Damage, insuredItem: Item): number =>
282	  reimbursementFor(damage.amount, insuredItem) - DEDUCTIBLE_PER_DAMAGE;
283	
284	// Each damage entry carries its own deductible, so this is a plain sum over
285	// the entries. The policy's cap is applied by the caller.
286	const desiredPayoutForIncident = (
287	  damages: Damage[],
288	  insuredItems: Item[],
289	): number =>
290	  damages.reduce(
291	    ({ total, unclaimedItems }, damage) => {
292	      rejectInvalidDamage(damage);
293	
294	      const { insuredItem, remainingItems } = claimInsuredItem(
295	        damage,
296	        unclaimedItems,
297	      );
298	
299	      return {
300	        total: total + payoutForDamage(damage, insuredItem),
301	        unclaimedItems: remainingItems,
302	      };
303	    },
304	    { total: 0, unclaimedItems: insuredItems },
305	  ).total;
306	
307	// A policy is created by a quote step; claims draw down its remaining cap.
308	// The insured items are retained because payout clauses depend on them.
309	type Policy = { remainingCap: number; items: Item[] };
310	
311	const capFor = (items: Item[]): number =>
312	  insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
313	
314	// A claim quotes its policy by the index of the step that created it, so
315	// policies are keyed by that index rather than collected in a list.
316	type ScenarioState = {
317	  customer: Customer;
318	  policiesByStep: Map<number, Policy>;
319	  precedingQuotes: number;
320	  results: ScenarioResult[];
321	};
322	
323	const initialState = (customer: Customer): ScenarioState => ({
324	  customer,
325	  policiesByStep: new Map(),
326	  precedingQuotes: 0,
327	  results: [],
328	});
329	
330	// Each step handler folds the state forward: it reads what earlier steps
331	// established and returns the state the following steps will see.
332	const applyQuote = (
333	  state: ScenarioState,
334	  step: QuoteStep,
335	  stepIndex: number,
336	): ScenarioState => {
337	  const { customer, precedingQuotes } = state;
338	
339	  step.items.forEach(rejectUninsurableItem);
340	
341	  const premium = quotePremium(step.items, { customer, precedingQuotes });
342	
343	  return {
344	    ...state,
345	    policiesByStep: new Map(state.policiesByStep).set(stepIndex, {
346	      remainingCap: capFor(step.items),
347	      items: step.items,
348	    }),
349	    precedingQuotes: precedingQuotes + 1,
350	    results: [...state.results, { premium }],
351	  };
352	};
353	
354	const applyClaim = (state: ScenarioState, step: ClaimStep): ScenarioState => {
355	  const policy = state.policiesByStep.get(step.policy);
356	
357	  if (policy === undefined) {
358	    throw new Error(`no policy was created by step ${step.policy}`);
359	  }
360	
361	  const desiredPayout = desiredPayoutForIncident(
362	    step.incident.damages,
363	    policy.items,
364	  );
365	  // The total payout per policy is capped, so a claim can pay out no more
366	  // than the cap the policy has left.
367	  const payout = Math.min(desiredPayout, policy.remainingCap);
368	  const remainingCap = policy.remainingCap - payout;
369	
370	  return {
371	    ...state,
372	    policiesByStep: new Map(state.policiesByStep).set(step.policy, {
373	      ...policy,
374	      remainingCap,
375	    }),
376	    results: [...state.results, { payout, remainingCap }],
377	  };
378	};
379	
380	const applyStep = (
381	  state: ScenarioState,
382	  step: Step,
383	  stepIndex: number,
384	): ScenarioState =>
385	  step.op === "quote"
386	    ? applyQuote(state, step, stepIndex)
387	    : applyClaim(state, step);
388	
389	export const runScenario = (scenario: unknown): ScenarioOutcome => {
390	  const { customer, steps } = scenario as Scenario;
391	
392	  const { results } = steps.reduce(applyStep, initialState(customer));
393	
394	  return { results };
395	};
